import {STAGES,LABELS,countWords,latest,stale,id,newRun,validateRun,stageReady,makePrompt,saveRecord,checks,exportMarkdown} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let runs=[],active='',view='revision',compare=false,selected='',pendingPrompt='',drafts={},noticeTimer,storageOK=true;
const demo=await fetch('./demo.json').then(r=>{if(!r.ok)throw Error('Demo unavailable');return r.json()}).catch(()=>null);
try{const saved=JSON.parse(localStorage.getItem('cuc-workbench-v1')||'null');if(saved){runs=saved.runs.filter(r=>!r.demo).map(validateRun);active=saved.active;}}catch{storageOK=false;}
if(demo)runs.unshift(validateRun(demo));if(!runs.length)runs.push(newRun());if(!runs.some(r=>r.id===active))active=runs[0].id;
function run(){return runs.find(r=>r.id===active)}
function toast(s){$('#notice').textContent=s;$('#notice').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').style.display='none',4500)}
function persist(){try{localStorage.setItem('cuc-workbench-v1',JSON.stringify({runs:runs.filter(r=>!r.demo),active}));storageOK=true;}catch{storageOK=false;toast('Browser storage is unavailable or full. Export your run now.');}}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function capture(){const el=$('#response');if(el)drafts[active+view]={text:el.value,model:$('#model').value,prompt:pendingPrompt};}
function selectedRecord(){return run().records[view]?.find(r=>r.id===selected)||latest(run(),view)}
function showStage(s){capture();view=s;selected='';compare=false;render();}
function nav(){const r=run();return `<aside><div class="run-box"><p class="eyebrow">Current run</p><select class="run-select" aria-label="Current run" id="runs">${runs.map(x=>`<option value="${esc(x.id)}" ${x.id===active?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><nav class="steps" aria-label="Workflow">${['brief',...STAGES,'evidence'].map((s,i)=>`<button class="step ${view===s?'active':''} ${latest(r,s)?'done':''}" data-stage="${s}" ${view===s?'aria-current="step"':''}><span class="num">${latest(r,s)?'✓':String(i+1).padStart(2,'0')}</span>${LABELS[s]}</button>`).join('')}</nav><div class="sidebar-links"><p class="eyebrow">Working record</p><p class="hint">${Object.values(r.records).reduce((a,x)=>a+x.length,0)} preserved outputs<br>${r.decisions.length} editorial decisions</p><button class="small" id="duplicate">${r.demo?'Use this brief':'Duplicate brief'}</button></div><div class="sidebar-note"><strong>${r.demo?'Recorded example':'Saved on this browser'}</strong><br>${r.demo?'These are supplied outputs from the pilot, not a live model run.':'Export a backup to move between devices. Nothing is sent to a model by this page.'}<br><a href="./prototype.zip" download>Python runner & source</a></div></aside>`}
function rightRail(record){const r=run(),c=checks(r,record),b=record?.brief||r.brief,notPost=['review','adjudication'].includes(view);return `<section class="checks" aria-label="Checks and brief"><div class="card"><div class="card-head"><h2>Checks</h2><span class="badge">Mechanical</span></div><div class="card-body"><div class="check"><strong>${notPost?'Post length checked separately':record?(c.length?'✓ Within range':'! Outside range'):'No output yet'}</strong><small>${notPost?'Review tables have no post word limit.':c.words+' words · target '+b.minWords+'–'+b.maxWords}</small></div><div class="check"><strong>${c.year?'✓ Source year appears':'— Source year not found'}</strong><small>Text match only; attribution still needs review.</small></div><div class="check"><strong>${c.sourceCaptured?'✓ Source text captured':'— Source linked only'}</strong><small>${c.sourceCaptured?'The same captured text travels with each prompt.':'Retrieval may differ between sessions. Paste source text for repeatability.'}</small></div><div class="check"><strong>Editorial review required</strong><small>Factual scope, voice, and evidence are judgments. No automatic accuracy score.</small></div></div></div><div class="card"><div class="card-head"><h2>Carried brief</h2></div><div class="card-body"><p class="side-title">Audience</p><p class="hint">${esc(b.audience)}</p><p class="side-title">Voice</p><p class="hint">${esc(b.voice)}</p><p class="side-title">Source</p><p class="hint">${esc(b.sourceTitle)} · ${esc(b.sourceYear)}</p>${/^https?:\/\//i.test(b.sourceUrl)?`<a class="footer-link" target="_blank" rel="noopener noreferrer" href="${esc(b.sourceUrl)}">Open original source ↗</a>`:''}</div></div></section>`}
function heading(title,desc){return `<div class="topline"><div><p class="eyebrow">Editorial workbench / ${run().demo?'Recorded pilot':'Working run'}</p><h1>${title}</h1><p class="sub">${desc}</p></div><span class="badge ${run().demo?'':'good'}">${run().demo?'Demo · read only':'Manual + API-ready'}</span></div>`}
function briefPage(){const r=run(),locked=r.demo||Object.values(r.records).some(a=>a.length);const field=(key,label,area=false)=>`<div class="field ${area?'full':''}"><label for="${key}">${label}</label>${area?`<textarea id="${key}" name="${key}" ${locked?'readonly':''} rows="${key==='sourceText'?9:3}">${esc(r.brief[key])}</textarea>`:`<input id="${key}" name="${key}" value="${esc(r.brief[key])}" ${locked?'readonly':''} ${key.includes('Words')?'type="number" min="1" max="100000"':''}>`}</div>`;return heading('Keep the brief attached.','The audience, source, voice, and length travel through every stage.')+`<div class="workspace"><section class="card"><div class="card-head"><h2>Brief & source</h2><span class="badge">${locked?'Locked to this run':'Ready to edit'}</span></div><div class="card-body">${locked?'<div class="banner">The brief is frozen once a response is saved. Use “Duplicate brief” to start a new experiment.</div>':''}<form id="brief-form"><div class="field"><label for="title">Run title</label><input id="title" value="${esc(r.title)}" ${locked?'readonly':''} maxlength="300" required></div><div class="fields">${field('format','Output format')}${field('audience','Audience')}${field('minWords','Minimum words')}${field('maxWords','Maximum words')}${field('voice','Voice instructions',true)}${field('constraints','Editorial requirements',true)}${field('sourceTitle','Source title')}${field('sourceAuthor','Author / publication')}${field('sourceYear','Source year')}${field('sourceUrl','Source URL')}${field('sourceText','Source text (recommended)',true)}</div><p class="hint">Paste material you can use. A URL alone requires the model to retrieve it. Source text stays on this browser until you export or send a prompt.</p>${!locked?'<button class="primary" type="submit">Save brief & draft →</button>':''}</form></div></section>${rightRail(null)}</div>`}
function stagePage(){const r=run(),record=selectedRecord(),writing=['draft','revision'].includes(view),history=r.records[view],ready=stageReady(r,view),past=record&&record.id!==latest(r,view)?.id,draft=drafts[active+view]||{text:'',model:''};try{pendingPrompt=draft.prompt||makePrompt(r,view)}catch{pendingPrompt=''}const titles={draft:['Draft from the source.','Write with the full brief, then preserve the first response.'],review:['Review the claims.','A reviewer proposes corrections. Evidence determines which ones deserve an edit.'],adjudication:['Review the review.','Accept, challenge, or reject changes before they reach the draft.'],revision:['What survived the edit?','Inspect the revision against its draft and the original brief.']};const [title,desc]=titles[view];return heading(title,desc)+`${r.demo?'<div class="banner">Run 001 · Recorded pilot. All three posts meet the 200–250-word limit: baseline 247, guided 227, revision 248. An earlier estimate was corrected during verification.</div>':''}${!ready&&!r.demo?'<div class="banner warning">An earlier stage is missing or outdated. Save current upstream records before continuing.</div>':''}${record&&stale(r,view,record)?'<div class="banner warning">This record used an earlier upstream response. It is preserved, but a new response is needed to continue this branch.</div>':''}<div class="workspace"><section><div class="card"><div class="card-head"><h2>${LABELS[view]} ${record?'record':'workspace'}</h2><div class="row">${view==='revision'&&record?'<button class="small" id="compare">'+(compare?'Single view':'Compare draft')+'</button>':''}${history.length?`<select id="version" class="versions" aria-label="Record version">${history.map((v,i)=>`<option value="${esc(v.id)}" ${record?.id===v.id?'selected':''}>Record ${i+1}${v===history.at(-1)?' · latest':''}</option>`).join('')}</select>`:''}</div></div>${record&&writing?`<div class="metrics"><div class="metric"><b>${countWords(record.text)}</b><span>words in this record</span></div><div class="metric"><b>${record.brief?.minWords||r.brief.minWords}–${record.brief?.maxWords||r.brief.maxWords}</b><span>carried word range</span></div><div class="metric"><b>${checks(r,record).length?'Within':'Outside'}</b><span>length requirement</span></div></div>`:''}<div class="card-body">${record?compare?`<div class="two-cols comparison"><div><p class="eyebrow">Guided draft</p><div class="article">${esc(r.records.draft.find(x=>x.id===record.parents.draft)?.text||latest(r,'draft')?.text||'No draft')}</div></div><div><p class="eyebrow">Revision</p><div class="article">${esc(record.text)}</div></div></div>`:`<div class="${writing?'article':'prose'}">${esc(record.text)}</div>`:'<div class="empty">No response saved yet.<br>Copy the prompt, run it in a fresh model session, and paste the response below.</div>'}${record?`<div class="divider"></div><p class="hint">${esc(record.model)} · ${record.createdAt?esc(new Date(record.createdAt).toLocaleString()):'Session time not supplied'} · ${esc(record.origin||'supplied response')}</p><details><summary>Prompt & provenance</summary><pre>${esc(record.prompt||'Exact submitted prompt was not supplied for this recorded response.')}</pre></details>`:''}</div></div>${r.demo?'':`<div class="card"><div class="card-head"><h2>${record?'Save another response':'Capture a response'}</h2><button class="small" id="copy-prompt" ${!ready?'disabled':''}>Copy stage prompt</button></div><div class="card-body"><p class="hint">Use a fresh model session. Every saved response is a new record; earlier responses stay intact.</p><details><summary>Inspect generated prompt</summary><pre id="prompt">${esc(pendingPrompt||'Complete earlier stages first.')}</pre></details><label class="visually-hidden" for="response">Model response</label><textarea id="response" class="editor" placeholder="Paste the ${LABELS[view].toLowerCase()} response here…">${esc(draft.text)}</textarea><div class="toolbar"><p class="hint" id="live-count">${countWords(draft.text)} words${writing?' · paste the post only':''}</p></div><div class="field"><label for="model">Model / session note</label><input id="model" value="${esc(draft.model)}" placeholder="e.g. model name · incognito · settings if known"></div><button class="primary" id="save-response" ${!ready?'disabled':''}>Save immutable record</button></div></div>`}${view==='adjudication'?decisionsPanel():''}${record?`<div class="row" style="margin-top:18px"><button class="primary" data-stage="${view==='revision'?'evidence':STAGES[STAGES.indexOf(view)+1]}">${view==='revision'?'Evidence & export': 'Continue to '+LABELS[STAGES[STAGES.indexOf(view)+1]].toLowerCase()} →</button></div>`:''}</section>${rightRail(writing?record:null)}</div>`}
function decisionsPanel(){const r=run();return `<div class="card"><div class="card-head"><h2>Human editorial decisions</h2></div><div class="card-body"><p class="hint">These judgments are included in the revision prompt. They remain separate from model reviews.</p>${r.decisions.map((d,i)=>`<div class="decision"><strong>${esc(d.claim)}</strong><div class="row" style="margin-top:10px"><span class="badge">${esc(d.verdict)}</span></div><p>${esc(d.reason)}</p></div>`).join('')}${r.demo?'':`<form id="decision-form"><div class="field"><label for="claim">Issue / proposed change</label><input id="claim" required maxlength="1000"></div><div class="field"><label for="verdict">Decision</label><select id="verdict"><option value="accept">Accept</option><option value="partial">Partially accept</option><option value="reject">Reject</option><option value="unresolved">Unresolved</option></select></div><div class="field"><label for="reason">Reason or exact correction</label><textarea id="reason" required rows="3"></textarea></div><button>Add decision</button></form>`}</div></div>`}
function evidencePage(){const r=run();return heading('An inspectable trail.','Export the brief, prompts, responses, decisions, and checks together.')+`<div class="workspace"><section><div class="card"><div class="card-head"><h2>Run package</h2><span class="badge">${r.demo?'Historical record':'Working record'}</span></div><div class="card-body"><div class="row"><button class="primary" id="export-json">Export run JSON</button><button id="export-md">Export readable report</button></div><p class="hint">JSON can be reimported here or used by the Python runner. The report includes every saved version.</p><div class="divider"></div>${STAGES.map(s=>`<div class="check"><strong>${LABELS[s]} · ${r.records[s].length} record${r.records[s].length===1?'':'s'}</strong><small>${latest(r,s)?`${esc(latest(r,s).model)}${stale(r,s)?' · outdated upstream inputs':''}`:'Not yet captured'}</small></div>`).join('')}<div class="divider"></div><h3>Run notes & limitations</h3>${r.demo?`<div class="prose">${esc(r.notes)}</div>`:`<label class="visually-hidden" for="notes">Run notes</label><textarea class="editor" id="notes" style="min-height:130px" placeholder="Record limitations, source retrieval, settings, or unresolved questions.">${esc(r.notes)}</textarea><button id="save-notes" class="small">Save notes</button>`}</div></div>${decisionsPanel()}${r.baseline?`<div class="card"><div class="card-head"><h2>Original baseline</h2><span class="badge">${countWords(r.baseline)} words</span></div><div class="card-body"><div class="article">${esc(r.baseline)}</div></div></div>`:''}<div class="card"><div class="card-head"><h2>Run with an API</h2></div><div class="card-body"><p class="sub">The hosted workbench uses copy-and-paste sessions. The included Python runner can execute the same four stages locally using an Anthropic API key. It requires captured source text and saves each response before continuing.</p><p class="hint">API usage is billed separately. No API key is requested or stored by this website. The adapter has been tested with simulated responses; a paid live call has not been run.</p><a href="https://github.com/thehofflebrock/context-under-compression" target="_blank" rel="noopener noreferrer">Open public source repository ↗</a></div></div></section>${rightRail(latest(r,'revision'))}</div>`}
function render(){const r=run();$('#app').innerHTML=`<header><div class="brand"><span class="mark" aria-hidden="true">[c]</span><div><strong>Context Under Compression</strong><small>Editorial workbench</small></div></div><div class="header-actions"><button id="import">Import run</button><button id="new">+ New run</button><button id="export-top">Export</button></div></header><div class="shell">${nav()}<main>${view==='brief'?briefPage():view==='evidence'?evidencePage():stagePage()}<div class="page-footer"><span>${r.demo?'Recorded pilot · no model call is running':storageOK?'Saved locally in this browser · export for backup':'Storage unavailable · export before leaving'}</span><span>Prototype 0.1 · Editorial judgment stays visible</span></div></main></div><input hidden type="file" id="file" accept="application/json,.json"><dialog id="confirm-dialog"><h2>Start with this brief?</h2><p>A new run will copy the brief only. Original responses and decisions stay in the recorded run.</p><div class="row"><button class="primary" id="confirm-duplicate">Create working run</button><button id="cancel-dialog">Cancel</button></div></dialog>`;bind();}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Prompt copied. Run it in a fresh model session.')}catch{toast('Clipboard unavailable. Open the generated prompt and select its text.')}}
function bind(){document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>showStage(b.dataset.stage));$('#runs').onchange=e=>{capture();active=e.target.value;selected='';compare=false;persist();render()};$('#new').onclick=()=>{capture();const r=newRun();runs.push(r);active=r.id;view='brief';selected='';persist();render()};$('#duplicate').onclick=()=>$('#confirm-dialog').showModal();$('#cancel-dialog').onclick=()=>$('#confirm-dialog').close();$('#confirm-duplicate').onclick=()=>{const r=newRun();r.brief=structuredClone(run().brief);r.title=run().title+' · new run';runs.push(r);active=r.id;view='brief';selected='';persist();render()};$('#export-top').onclick=()=>showStage('evidence');$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5e6)return toast('Run files must be smaller than 5 MB.');try{let r=validateRun(JSON.parse(await f.text()));r=structuredClone(r);r.id=id();r.demo=false;r.title+=' · imported';runs.push(r);active=r.id;view='evidence';selected='';persist();render();toast('Run imported without replacing existing records.')}catch(err){toast(err.message)}};
if($('#brief-form'))$('#brief-form').onsubmit=e=>{e.preventDefault();const r=run(),b={...r.brief};for(const k of Object.keys(b))b[k]=k.includes('Words')?Number($('#'+k).value):$('#'+k).value.trim();if(!b.sourceTitle||(!b.sourceUrl&&!b.sourceText))return toast('Add a source title and either its URL or captured text.');try{validateRun({...r,brief:b})}catch(err){return toast(err.message)}r.title=$('#title').value.trim()||'Untitled run';r.brief=b;persist();view='draft';render()};
if($('#compare'))$('#compare').onclick=()=>{compare=!compare;render()};if($('#version'))$('#version').onchange=e=>{capture();selected=e.target.value;render()};if($('#copy-prompt'))$('#copy-prompt').onclick=()=>copy(pendingPrompt);if($('#response'))$('#response').oninput=e=>{$('#live-count').textContent=countWords(e.target.value)+' words'+(['draft','revision'].includes(view)?' · paste the post only':'')};if($('#save-response'))$('#save-response').onclick=()=>{try{saveRecord(run(),view,$('#response').value,$('#model').value,pendingPrompt);delete drafts[active+view];selected='';persist();render();toast('New record saved. Earlier versions are unchanged.')}catch(err){toast(err.message)}};
if($('#decision-form'))$('#decision-form').onsubmit=e=>{e.preventDefault();run().decisions.push({id:id(),claim:$('#claim').value.trim(),verdict:$('#verdict').value,reason:$('#reason').value.trim()});persist();render();toast('Decision recorded for the next revision prompt.')};if($('#export-json'))$('#export-json').onclick=()=>download('content-run.json',JSON.stringify(run(),null,2),'application/json');if($('#export-md'))$('#export-md').onclick=()=>download('content-run-report.md',exportMarkdown(run()),'text/markdown');if($('#save-notes'))$('#save-notes').onclick=()=>{run().notes=$('#notes').value;persist();toast('Notes saved.')};}
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_editorial_run',description:'Read the current brief, record counts, and mechanical revision checks. Does not call an AI model.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({title:run().title,brief:run().brief,records:Object.fromEntries(STAGES.map(s=>[s,run().records[s].length])),checks:checks(run(),latest(run(),'revision'))})},{name:'navigate_editorial_stage',description:'Open a workflow stage without generating or changing content.',inputSchema:{type:'object',properties:{stage:{type:'string',enum:['brief',...STAGES,'evidence']}},required:['stage'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['brief',...STAGES,'evidence'].includes(input.stage))throw Error('Unknown stage');showStage(input.stage);return {stage:view}}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
window.addEventListener('beforeunload',e=>{if($('#response')?.value.trim()){e.preventDefault();e.returnValue=''}});
